//! Compatibility of stored password hashes across `bcrypt` crate versions.
//!
//! These tests exercise the third-party crate directly (no application code): they pin that hashes
//! written by earlier versions and by other implementations stay verifiable after a dependency
//! upgrade. Login/registration behaviour itself is covered by the user and auth tests.
const PASSWORD: &str = "Fixture-Passwort-123";
// Generated independently with `htpasswd -nbBC 10` (Apache, `$2y$` prefix)
const HASH_2Y: &str = "$2y$10$umcqNcJC39ekVAqlH3dJ1.UnFb7dolPc4pmjl6.yP0Xa/1TbJIdqq";
// Generated by the bcrypt crate before the upgrade (0.17, `$2b$` prefix)
const HASH_2B: &str = "$2b$10$N3K.yoRvSS2ScnBt1OsZT.nu/lv1bvq4msB2/ipQ3Z4jpK9lXTTr2";

#[test]
fn test_existing_password_hashes_stay_verifiable() {
    assert!(bcrypt::verify(PASSWORD, HASH_2Y).unwrap());
    assert!(bcrypt::verify(PASSWORD, HASH_2B).unwrap());
}

#[test]
fn test_wrong_password_is_rejected_for_existing_hashes() {
    assert!(!bcrypt::verify("falsches-passwort", HASH_2Y).unwrap());
    assert!(!bcrypt::verify("falsches-passwort", HASH_2B).unwrap());
}

#[test]
fn test_new_hash_uses_cost_10_and_roundtrips() {
    let hash = bcrypt::hash(PASSWORD, 10).unwrap();
    assert!(
        hash.starts_with("$2b$10$"),
        "unexpected hash format: {hash}"
    );
    assert!(bcrypt::verify(PASSWORD, &hash).unwrap());
    assert_ne!(
        hash,
        bcrypt::hash(PASSWORD, 10).unwrap(),
        "salt must be random"
    );
}
